local M32 = 4294967296.0

local function mul32(a, b)
  a = a % M32
  b = b % M32
  local al = a % 65536
  local ah = floor_(a / 65536)
  local bl = b % 65536
  local bh = floor_(b / 65536)
  return (al * bl + (ah * bl + al * bh) % 65536 * 65536) % M32
end

local function shr(x, k)
  return floor_((x % M32) / (2 ^ k))
end

local function rotl(x, k)
  k = k % 32
  if k == 0 then return x % M32 end
  return (x % M32 * 2 ^ k) % M32 + floor_((x % M32) / 2 ^ (32 - k))
end

local function xorb(a, b)
  if bxor_ then return bxor_(a, b) end
  local r, bit = 0, 1
  local i = 0
  while i < 32 do
    local x, y = a % 2, b % 2
    if x ~= y then r = r + bit end
    a = floor_(a / 2)
    b = floor_(b / 2)
    bit = bit * 2
    i = i + 1
  end
  return r
end

local function mixz(x)
  x = x % M32
  x = xorb(x, shr(x, 16))
  x = mul32(x, 2246822507)
  x = xorb(x, shr(x, 13))
  x = mul32(x, 3266489909)
  x = xorb(x, shr(x, 16))
  return x
end

local function ks(k0, k1, pos)
  local c = floor_(pos / 4)
  local s = xorb(c, mul32(k0, 2654435761))
  s = (s + mul32(k1, 2135587861)) % M32
  s = xorb(s, rotl(k0, c % 16 + 1))
  s = mixz(s)
  s = xorb(s, rotl(k1, 32 - (shr(c, 5) % 16 + 1)))
  s = mul32(s, k0 % 2 == 0 and k0 + 1 or k0)
  return mixz(s)
end

local function decrypt(i)
  local e = SC[i]
  if e == nil then return nil end
  if e[4] ~= nil then return e[4] end
  local h = e[1]
  local k0, k1 = e[2], e[3]
  local n = #h / 2
  local bytes = {}
  local x = 0
  while x < n do
    local w = ks(k0, k1, x)
    local kb = floor_(w / 2 ^ (x % 4 * 8)) % 256
    bytes[x + 1] = xorb(tonumber(sub_(h, x * 2 + 1, x * 2 + 2), 16), kb) % 256
    x = x + 1
  end
  local out = {}
  x = 1
  while x <= n do
    out[x] = char_(bytes[x])
    x = x + 1
  end
  local str = concat_(out)
  local v
  if e[5] == 2 then v = tonumber(str) else v = str end
  e[4] = v
  return v
end

